// === Tab: mySketch ===
var d = [];
var rain;

function preload() {
	rain = loadSound('https://openprocessing.org/sketch/702792/files/heavyRain.wav');
}

function setup() {
  createCanvas(windowWidth, windowHeight);

  for (var i = 0; i < 200; i++) {
    d.push(new Drop(random(0, windowWidth), random(0, windowHeight), random(1, 1.8)));
		// generate i raindrops at the start, these will be reused throughout
  }

	noLoop();
}

function draw() {
	// fade effect: shade background with alpha bkgd
	noStroke();
  fill(0, 30);
  rect(0, 0, width, height);

	rain.setVolume(map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, 1000, 0.1, 1));

	// i'm guessing this updates each particle on screen?
  for (var i = 0; i < d.length; i++) {
    d[i].displ();
  }
}

function mouseClicked() {
	// user interaction is required before autoplay, otherwise i wouldn't do this
	rain.setVolume(0.4);
	rain.loop();

	loop(); // let's start draw()
}

function windowResized(){
  resizeCanvas(window.innerWidth, window.innerHeight);
}

// === Tab: Drop ===
function Drop(x, y, sp) {
  var x1 = x;
  var y1 = y;
  var x2;
  var y2;
  var s = sp;

	var len = 4;

  this.displ = function() {
    // converts mouse position. could also use map() to avoid mx <= 0
		var mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / 120;
    if (mx <= 0) {
      mx = 0.5; // default, works as a failsafe. old one was too slow for me
    }

    y1 = y1 + s * mx; // scales speed according to mouse position
    x2 = x1;
    y2 = y1 + len; // length of raindrops, change if they're too long/short

		len += 0.02 * mx; // length didn't look right when approaching the lowest/highest speed, so this tweaks it

		// draws raindrop
    stroke(200);
    line(x1, y1, x2, y2);

    if (y1 >= windowHeight - 80) { // did the drop hit the ground?
			noFill();
      noStroke();
      fill(255, 150);
      ellipse(x1, windowHeight - random(5, 50), random(3, 9), random(2, 5)); // then draw a splash

			// renews the drop by sending it back to the top (no need to generate new ones)
			x1 = random(0, windowWidth);
      y1 = -120;
			len = 4;
    }
  }

}

